<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import type {PairedResult,Run,Result,SingleResult} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Empty from '../components/common/Empty.vue';import WindowComparison from '../components/WindowComparison.vue';import ReplicationChart from '../components/ReplicationChart.vue';import ServiceTimeline from '../components/ServiceTimeline.vue';import PairedComparison from '../components/PairedComparison.vue';import PairedDiffChart from '../components/PairedDiffChart.vue';import RunConfigCard from '../components/RunConfigCard.vue';import {number,percent} from '../utils/format';const props=defineProps<{data:Workspace}>();const selected=ref('');const run=computed(()=>props.data.runs.find(r=>r.id===selected.value)||props.data.runs[0]);const result=computed<Result|undefined>(()=>run.value?.result);const paired=computed<PairedResult|null>(()=>result.value&&result.value.mode==='paired'?result.value as PairedResult:null);const single=computed<SingleResult|null>(()=>result.value&&result.value.mode!=='paired'?result.value as SingleResult:null);const scenario=computed(()=>props.data.scenarios.find(s=>s.id===run.value?.scenario_id));const timelineEvents=computed(()=>paired.value?paired.value.candidate.simulation.timeline:single.value?.simulation.timeline||[]);const timelineWindows=computed(()=>paired.value?paired.value.candidate.windows:single.value?.analytic.windows||1);const comparisonRows=computed(()=>paired.value?paired.value.comparison:single.value?.comparison||[]);
</script><template><PageHeading code="05 / WAITING & LOAD" title="理论给边界，仿真看波动。" description="解析稳态值与有限期仿真分开展示。配对试验在同一批到达与服务下逐次比较两侧窗口，差值区间按配对差值计算。rho≥1时没有有限稳态等待；暂态数值不能证明稳定。"/><div class="run-selector"><label>运行记录<select aria-label="选择运行记录" :value="run?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}} · {{r.created_at.slice(11,19)}}</option></select></label><Status v-if="run" :value="run.status"/><span v-if="scenario" class="mode-tag">{{scenario.candidate_windows?'配对试验':'单方案'}}</span></div><Empty v-if="!run">请前往窗口方案，保存配置后运行后台预演。</Empty><Notice v-else-if="run.status!=='completed'" :error="run.status==='failed'">{{run.status==='failed'?run.error:'预演已进入独立worker队列，结果会自动刷新。'}}</Notice><template v-else-if="paired"><Notice v-if="!paired.baseline.analytic.stable||!paired.candidate.analytic.stable" error>基准或候选侧 ρ ≥ 1：至少一侧没有有限稳态等待。配对仿真差值仍为指定有限时域的暂态结果，不能证明稳定。</Notice><section class="paper"><div class="section-heading"><h2>配对试验：{{paired.baseline.windows}} 窗口 vs {{paired.candidate.windows}} 窗口</h2><span>同剖面 · 同随机参数 · {{paired.paired.replications.length}}次配对重复</span></div><RunConfigCard v-if="paired.config" :config="paired.config"/><PairedComparison :result="paired"/></section><section class="paper"><h2>同输入率，比较窗口数</h2><WindowComparison :rows="paired.comparison"/><p class="caption">理论列来自 Erlang-C 解析；配对差值来自下方逐次仿真，两者不可互相替代。</p></section><div class="result-grid"><section class="paper"><h2>逐次配对差值，围绕零吗？</h2><PairedDiffChart :rows="paired.paired.replications"/><div class="simulation-settings"><span>{{paired.config?.duration_minutes}}分钟观测</span><span>{{paired.config?.warmup_minutes}}分钟预热</span><span>seed {{paired.config?.seed}}</span><span>基准−候选</span></div></section><aside class="model-note"><span class="eyebrow">PAIRED DESIGN</span><h2>同一批到达，只换窗口。</h2><p>每次重复两侧共用到达时刻与服务时长，随机波动在差值中相抵，因此逐次差值的区间通常比两侧独立均值相减更窄。相同窗口数差值为零，交换两侧后差值反号。</p><small>{{paired.paired.ci_method}}</small></aside></div><div class="result-grid"><section class="paper"><h2>基准 {{paired.baseline.windows}} 窗口 · 每次重复</h2><ReplicationChart :rows="paired.baseline.simulation.replications"/><div class="simulation-settings"><span>平均等待 {{number(paired.baseline.simulation.mean_wait_minutes)}} 分钟</span><span>95%区间 {{number(paired.baseline.simulation.mean_wait_ci95[0])}}—{{number(paired.baseline.simulation.mean_wait_ci95[1])}}</span><span>忙碌 {{percent(paired.baseline.simulation.busy_fraction)}}</span></div></section><section class="paper"><h2>候选 {{paired.candidate.windows}} 窗口 · 每次重复</h2><ReplicationChart :rows="paired.candidate.simulation.replications"/><div class="simulation-settings"><span>平均等待 {{number(paired.candidate.simulation.mean_wait_minutes)}} 分钟</span><span>95%区间 {{number(paired.candidate.simulation.mean_wait_ci95[0])}}—{{number(paired.candidate.simulation.mean_wait_ci95[1])}}</span><span>忙碌 {{percent(paired.candidate.simulation.busy_fraction)}}</span></div></section></div><section class="paper"><h2>候选侧窗口服务时间轴（最后一次重复）</h2><ServiceTimeline :events="timelineEvents" :windows="timelineWindows"/></section><section class="paper"><h2>假设与适用边界</h2><ol class="assumption-list"><li v-for="a in paired.assumptions" :key="a">{{a}}</li></ol></section></template><template v-else-if="single"><Notice v-if="!single.analytic.stable" error>ρ = {{number(single.analytic.rho)}} ≥ 1：系统不稳定，无有限稳态平均等待。下方仿真仅为指定有限时域的暂态结果。</Notice><section class="paper"><div class="section-heading"><h2>本次预演结果</h2><span>λ {{number(single.analytic.arrival_rate,3)}} / μ {{number(single.analytic.service_rate,3)}} 每分钟</span></div><RunConfigCard v-if="single.config" :config="single.config"/><div class="result-metrics"><div><small>理论稳态平均等待</small><b>{{single.analytic.stable?number(single.analytic.mean_wait_minutes):'无有限值'}}</b><em>{{single.analytic.stable?'分钟':'ρ ≥ 1'}}</em></div><div class="featured"><small>有限期仿真平均等待</small><b>{{number(single.simulation.mean_wait_minutes)}}</b><em>分钟</em></div><div><small>重复试验95%区间</small><b class="range">{{number(single.simulation.mean_wait_ci95[0])}}—{{number(single.simulation.mean_wait_ci95[1])}}</b><em>分钟 / 正态近似</em></div><div><small>有限期窗口忙碌比例</small><b>{{percent(single.simulation.busy_fraction)}}</b><em>按服务区间与观测期交集计算</em></div></div><WindowComparison :rows="single.comparison"/><p class="caption">旧单方案运行仅对照各次预演均值，不含配对差值；如需差值区间请新建配对方案。</p></section><div class="result-grid"><section class="paper"><h2>每次重复，会等多久？</h2><ReplicationChart :rows="single.simulation.replications"/><div class="simulation-settings"><span>{{single.simulation.duration_minutes}}分钟观测</span><span>{{single.simulation.warmup_minutes}}分钟预热</span><span>seed {{single.simulation.seed}}</span></div></section><aside class="model-note"><span class="eyebrow">MODEL BOUNDARIES</span><h2>区间里，没有输入误差。</h2><p>此区间只反映同一模型下重复随机流的波动。到达率估计、峰值变化与服务差异需要另行复核。</p><small>{{single.simulation.ci_method}}</small></aside></div><section class="paper"><h2>窗口服务时间轴</h2><ServiceTimeline :events="single.simulation.timeline" :windows="single.analytic.windows"/></section><section class="paper"><h2>假设与适用边界</h2><ol class="assumption-list"><li v-for="a in single.assumptions" :key="a">{{a}}</li></ol></section></template></template>
